    g=[row[:] for row in inp]; h=len(g); w=len(g[0])
    def comps(v):
        seen=[[False]*w for _ in range(h)]; out=[]
        for i in range(h):
            for j in range(w):
                if g[i][j]==v and not seen[i][j]:
                    st=[(i,j)]; cells=[]
                    while st:
                        y,x=st.pop(); cells.append((y,x))
                        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and g[ny][nx]==v and not seen[ny][nx]:
                                seen[ny][nx]=True; st.append((ny,nx))
                    out.append(cells)
        return out
    rings=comps(2)
    cen=[(sum(y for y,_ in c)/len(c), sum(x for _,x in c)/len(c)) for c in rings]
    mcells=[(y,x) for y in range(h) for x in range(w) if g[y][x] not in (0,2)]
    res={m:g[m[0]][m[1]] for m in mcells}
    # assign each marker to nearest ring centroid (Euclidean)
    rm={m:min(range(len(rings)),key=lambda k:(m[0]-cen[k][0])**2+(m[1]-cen[k][1])**2) for m in mcells}
    for ri in range(len(rings)):
        pts=sorted([p for p in mcells if rm[p]==ri], key=lambda p:(p[0]-cen[ri][0])**2+(p[1]-cen[ri][1])**2)
        # pair opposite quadrants: sort by angle; pair k with n-1-k
        ang=sorted([math.atan2(p[0]-cen[ri][0],p[1]-cen[ri][1]) for p in pts])
        n=len(pts)
        for k in range(n//2):
            a,b=pts[ang.index(ang[k])],pts[ang.index(ang[-1-k])]
            res[a],res[b]=res[b],res[a]
    for m in mcells: g[m[0]][m[1]]=res[m]
    # rays away from centroid, single diagonal direction = sign(dx),sign(dy) away
    for m in mcells:
        v=res[m]; y,x=m
        cs,cx=cen[rm[m]]; dy=1 if y>=cs else -1; dx=1 if x>=cx else -1
        yy,xx=y+dy,x+dx
        while 0<=yy<h and 0<=xx<w:
            if g[yy][xx]!=0: break
            g[yy][xx]=v; yy+=dy; xx+=dx
    return g
