                    st=[(i,j)]; cells=[]
                    while st:
                        y,x=st.pop(); cells.append((y,x))
                        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and g[ny][nx]==v and not seen[ny][nx]:
                                seen[ny][nx]=True; st.append((ny,nx))
                    out.append(cells)
        return out
    rings=comps(2); cen=[(sum(y for y,_ in c)/len(c), sum(x for _,x in c)/len(c)) for c in rings]
    mcells=[(y,x) for y in range(h) for x in range(w) if g[y][x] not in (0,2)]
    # assign: diagonally adjacent (Chebyshev 1) to a ring cell -> that ring; else nearest centroid
    rm={}
    for m in mcells:
        cand=[]
        for k,ringc in enumerate(rings):
            if any(max(abs(m[0]-r[0]),abs(m[1]-r[1]))==1 for r in ringc):
                cand.append((0,k))
        if cand:
            rm[m]=cand[0][1]; continue
        best=None
        for k,(cy,cx) in enumerate(cen):
            d=(m[0]-cy)**2+(m[1]-cx)**2
            if best is None or d<best[0]: best=(d,k)
        rm[m]=best[1]
    cols={m:g[m[0]][m[1]] for m in mcells}
