        ang=sorted(math.atan2(p[0]-cen[ri][0],p[1]-cen[ri][1]) for p in pts)
        ord_=[pts[ang.index(a)] for a in ang]
        if rot=='ccw':
            newc=[cols[ord_[(k+1)%n]] for k,p in enumerate(ord_)]
        else:
            newc=[cols[ord_[(k-1)%n]] for k,p in enumerate(ord_)]
        for k,p in enumerate(ord_): cols[p]=newc[k]
