    for m in mcells:
        adj=[k for k,rng in enumerate(rings) if any(max(abs(m[0]-r[0]),abs(m[1]-r[1]))==1 for r in rng)]
        if adj:
            k=min(adj); cs[k].append(m)
        else:
            # assign stray to nearest ring
            best=min(range(len(cen)), key=lambda k:(m[0]-cen[k][0])**2+(m[1]-cen[k][1])**2)
            cs[best].append(m)
    newc={}
    for k,pts in cs.items():
        ang=sorted(math.atan2(p[0]-cen[k],p[1]-cen[k]) for p in pts)
        o=[p for p,_ in zip(pts,ang)]  # keep relative order
        n=len(o)
        if conf['cycle']=='prev':
            mp={o[(k+1)%n]: o[k] for k in range(n)}   # o[k] takes o[k+1]'s color? define: new[o[k]]=old[o[prev]]
        else:
            mp={o[k]: o[(k+1)%n] for k in range(n)}
        newc.update(mp)
    for m in mcells: g[m[0]][m[1]]=newc.get(m,g[m[0]][m[1]])
    # erase strays
    strays=[m for m in mcells if not any(max(abs(m[0]-r[0]),abs(m[1]-r[1]))==1 for c in rings for r in c)]
    for m in strays: g[m[0]][m[1]]=0
    # rays
    for m in mcells:
        if m in strays: continue
        v=newc[m]; y,x=m; cs_,cx_=cen[[k for k,p in cs.items() if m in p][0]]
        dy=1 if y>cs_ else -1; dx=1 if x>cx_ else -1
        yy,xx=y+dy,x+dx
        while 0<=yy<h and 0<=xx<w:
            obs=g[yy][xx]
            if conf['raystop'](obs,yy,xx,g): break
            g[yy][xx]=v; yy+=dy; xx+=dx
    return g

