        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(v,g,h,w):
    seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==v and not seen[i][j]:
                st=[(i,j)]; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==v and not seen[ny][nx]:
                            seen[ny][nx]=True; st.append((ny,nx))
                out.append(cells)
    return out

def solve(inp, rot='cw'):
    g=[r[:] for r in inp]; h=len(g); w=len(g[0])
    rings=comps(2,g,h,w); cen=[(sum(y for y,_ in c)/len(c), sum(x for _,x in c)/len(c)) for c in rings]
    mcells=[(y,x) for y in range(h) for x in range(w) if g[y][x] not in (0,2)]
    cs=collections.defaultdict(list)
    for m in mcells:
        adj=[k for k,rng in enumerate(rings) if any(max(abs(m[0]-r[0]),abs(m[1]-r[1]))==1 for r in rng)]
        idx=adj[0] if adj else min(range(len(cen)), key=lambda k:(m[0]-cen[k][0])**2+(m[1]-cen[k][1])**2)
        cs[idx].append(m)
    newc={}
    for k,pts in list(cs.items()):
        ang=[math.atan2(p[0]-cen[k][0], p[1]-cen[k][1]) for p in pts]
        idxs=sorted(range(len(pts)), key=lambda i: ang[i])
        n=len(idxs)
        if rot=='cw':
            for i in range(n):
                prev=idxs[(i-1)%n]
                newc[pts[idxs[i]]]=inp[pts[prev][0]][pts[prev][1]]
        else:
            for i in range(n):
                nxt=idxs[(i+1)%n]
                newc[pts[idxs[i]]]=inp[pts[nxt][0]][pts[nxt][1]]
    # recolor markers (they keep positions)
    g2=[r[:] for r in g]
    for m in mcells: g2[m[0]][m[1]]=newc.get(m,g[m[0]][m[1]])
    # rays from each marker, stopping at any nonzero
    for m in mcells:
        v=newc.get(m,g[m[0]][m[1]])
        ki=next(iter([p for p in cs if m in cs[p]]))
        cy_,cx_=cen[ki]; dy=1 if m[0]>cy_ else -1; dx=1 if m[1]>cx_ else -1
        yy,xx=m[0]+dy,m[1]+dx
        while 0<=yy<h and 0<=xx<w:
            if g2[yy][xx]==0:
                g2[yy][xx]=v; yy+=dy; xx+=dx
            else: break
    return g2

